class Solution {
    public int maxProfit(int[] prices) {
        return explore(prices, 0, false);
    }

    private int explore(int[] prices, int day, boolean holding) {
        if (day == prices.length) {
            return holding ? Integer.MIN_VALUE / 2 : 0;
        }
        int best = explore(prices, day + 1, holding);
        if (holding) {
            best = Math.max(best, prices[day] + explore(prices, day + 1, false));
        } else {
            best = Math.max(best, -prices[day] + explore(prices, day + 1, true));
        }
        return best;
    }
}

